// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import * as queries from "../../../main/frontend/graph-explorer/facet-queries.ts";
import { QueryFailure } from "../../../main/frontend/graph-explorer/request-batching.ts";

const uri = (value) => ({ type: "uri", value });
const literal = (value, extra = {}) => ({ type: "literal", value: String(value), ...extra });
const row = (value, count, label, language) => ({
  value: uri(value), count: literal(count),
  ...(label ? { valueLabel: literal(label, language ? { "xml:lang": language } : {}) } : {}),
});
const sources = Array.from({ length: 241 }, (_, index) => `urn:source:${index}`);
const count = (...args) => {
  assert.equal(typeof queries.countFacetValues, "function", "repository counting must consume every bounded source batch");
  return queries.countFacetValues(...args);
};

test("repository counts deduplicate sources and sum every batch without counting each label again", async () => {
  const requested = [];
  const result = await count([...sources, ...sources, "bad iri"], "urn:p", "urn:g", ["nb", "en"], async (query) => {
    assert.doesNotMatch(query, /LIMIT\s+100\b/i, "a batch must not discard values before the global top 100 is known");
    const ids = [...query.matchAll(/<urn:source:\d+>/g)].map(([id]) => id.slice(1, -1));
    assert.ok(ids.length <= 120, "source requests remain bounded");
    requested.push(...ids);
    return { results: { bindings: [
      row("urn:shared", ids.length, "Shared"),
      row("urn:shared", ids.length, "Felles", "nb"),
      row("urn:shared", ids.length, "Felles alternative", "nb"),
      ...(ids.includes("urn:source:240") ? [row("urn:later", 1, "Later")] : []),
    ] } };
  });
  assert.deepEqual(requested, sources);
  assert.deepEqual(result, [{ id: "urn:shared", label: "Felles", count: 241 }, { id: "urn:later", label: "Later", count: 1 }]);
});

test("the global top 100 includes values below the top 100 of every individual batch", async () => {
  let batch = 0;
  const result = await count(sources, "urn:p", "default", ["en"], async (query) => {
    assert.doesNotMatch(query, /LIMIT\s+100\b/i);
    const index = batch++;
    return { results: { bindings: [
      ...Array.from({ length: 100 }, (_, value) => row(`urn:local:${index}:${value}`, 2, `Local ${index}:${value}`)),
      row("urn:global", 1, "Global"),
    ] } };
  });
  assert.equal(batch, 3);
  assert.equal(result.length, 100);
  assert.deepEqual(result[0], { id: "urn:global", label: "Global", count: 3 });
  assert.equal(new Set(result.map(({ id }) => id)).size, 100);
});

test("obsolete and cancelled count workflows stop before the next batch and return no partial counts", async () => {
  let current = true;
  let requests = 0;
  const obsolete = await count(sources, "urn:p", "default", ["en"], async () => {
    requests++;
    current = false;
    return { results: { bindings: [row("urn:shared", 120, "Shared")] } };
  }, { isCurrent: () => current });
  assert.equal(obsolete, null);
  assert.equal(requests, 1);
  const controller = new AbortController();
  controller.abort();
  const cancelled = await count(sources, "urn:p", "default", ["en"], async () => {
    assert.fail("an aborted count must not start a request");
  }, { signal: controller.signal });
  assert.equal(cancelled, null);
});

test("all batches share the cancellation signal and empty source sets make no request", async () => {
  const controller = new AbortController();
  let requests = 0;
  const result = await count(sources, "urn:p", "default", ["en"], async (query, signal) => {
    assert.equal(signal, controller.signal);
    requests++;
    return { results: { bindings: [] } };
  }, { signal: controller.signal });
  assert.equal(requests, 3);
  assert.deepEqual(result, []);
  assert.deepEqual(await count([], "urn:p", "default", ["en"], () => assert.fail("empty sources")), []);
});

test("HTTP 413 splits oversized long-IRI count batches until every distinct source is counted once", async () => {
  const longSources = sources.map((source) => `${source}:${"x".repeat(5000)}`);
  const accepted = [];
  const rejectedSizes = [];
  let requests = 0;
  const controller = new AbortController();
  const result = await count([...longSources, ...longSources], "urn:p", "urn:g", ["nb", "en"], async (query, signal) => {
    assert.equal(signal, controller.signal);
    requests++;
    const values = /VALUES\s+\?source\s*\{([^}]+)\}/.exec(query)?.[1] ?? "";
    const ids = [...values.matchAll(/<([^>]+)>/g)].map(([, id]) => id);
    // The server's default is 150,000 characters; 120 supported long IRIs can exceed it several times over.
    if (query.length > 150_000) {
      rejectedSizes.push(ids.length);
      throw new QueryFailure("The query is too long for the Workbench.", 413);
    }
    accepted.push(...ids);
    return { results: { bindings: [
      row("urn:shared", ids.length, "Shared"),
      row("urn:shared", ids.length, "Felles", "nb"),
      ...(ids.includes(longSources.at(-1)) ? [row("urn:later", 1, "Later")] : []),
    ] } };
  }, { signal: controller.signal });
  assert.ok(rejectedSizes.includes(120));
  assert.ok(rejectedSizes.some((size) => size < 120), "rejected child batches must split again");
  assert.ok(requests <= 2 * longSources.length, "each failed batch must make bounded progress");
  assert.equal(accepted.length, longSources.length);
  assert.equal(new Set(accepted).size, longSources.length);
  assert.deepEqual(new Set(accepted), new Set(longSources));
  assert.deepEqual(result, [{ id: "urn:shared", label: "Felles", count: 241 }, { id: "urn:later", label: "Later", count: 1 }]);
});

for (const cancellation of ["obsolete", "aborted"]) {
  test(`a count workflow ${cancellation} during HTTP 413 stops without retrying or returning partial counts`, async () => {
    let current = true;
    let requests = 0;
    const controller = new AbortController();
    const result = await count(sources, "urn:p", "default", ["en"], async () => {
      requests++;
      if (requests === 1) {
        return { results: { bindings: [row("urn:shared", 120, "Shared")] } };
      }
      if (cancellation === "obsolete") current = false;
      else controller.abort();
      throw new QueryFailure("The query is too long for the Workbench.", 413);
    }, { signal: controller.signal, isCurrent: () => current });
    assert.equal(result, null);
    assert.equal(requests, 2, "discard the prior accepted batch and make no request after cancellation");
  });
}

test("a single-source HTTP 413 propagates because there is no smaller source batch", async () => {
  const failure = new QueryFailure("Even one source is too long.", 413);
  let requests = 0;
  await assert.rejects(count(["urn:single"], "urn:p", "default", ["en"], async () => {
    requests++;
    throw failure;
  }), (error) => error === failure);
  assert.equal(requests, 1);
});

test("count batching propagates other errors without splitting or retrying", async () => {
  const failure = new QueryFailure("Repository unavailable.", 503);
  let requests = 0;
  await assert.rejects(count(sources, "urn:p", "default", ["en"], async () => {
    requests++;
    throw failure;
  }), (error) => error === failure);
  assert.equal(requests, 1);
});
